CREATE FUNCTION [dbo].[LIST_SALARY22TOFILE](@Forms___F_MENU_BIM___MMO [int], @Forms___Baseknow___HOLA [int], @Forms___Baseknow___HSAY [int], @Forms___Baseknow___HJAZ [int], @Forms___Baseknow___HNAH [int], @Forms___Baseknow___HCON [int], @Forms___Baseknow___HKHA [int], @HOKMDATE [bigint], @Forms___Baseknow___SAGHFH [int], @Forms___Baseknow___HSANP [int], @Forms___Baseknow___HSHI [int], @Forms___Baseknow___YEA [smallint], @Forms___Baseknow___HEZA [int], @Forms___Baseknow___HBON [int], @Forms___Baseknow___HTAHOL [int]) RETURNS TABLE AS RETURN (SELECT COUNT(CODE) AS DSK_NUM, SUM(DAYS) AS DSK_TDD, SUM(CASE WHEN DAYS > 0 THEN SALARY_DAYLY ELSE 0 END) AS DSK_TROOZ, SUM(mosalary) AS DSK_TMAH, SUM(MAZMASH) AS DSK_TMAZ, SUM(jamazsalmash) AS DSK_TTOTL, SUM(bimper) AS DSK_TBIME, SUM(CASE WHEN TAB56 = 0 THEN jmazsalmash * 0.2 ELSE 0 END) AS DSK_TKOSO, SUM((jmazsalmash - H3BIM) * 0.03) AS DSK_BIC, WDATE, SUM(jmazsalmash) AS DSK_TMASH FROM dbo.LIST_SALARY22(@Forms___F_MENU_BIM___MMO, @Forms___Baseknow___HOLA, @Forms___Baseknow___HSAY, @Forms___Baseknow___HJAZ, @Forms___Baseknow___HNAH, @Forms___Baseknow___HCON, @Forms___Baseknow___HKHA, @HOKMDATE, @Forms___Baseknow___SAGHFH, @Forms___Baseknow___HSANP, @Forms___Baseknow___HSHI, @Forms___Baseknow___YEA, @Forms___Baseknow___HEZA, @Forms___Baseknow___HBON, @Forms___Baseknow___HTAHOL) AS LIST_SALARY22 GROUP BY WDATE)
